import{_ as i,h as o,i as l,c as n,v as e,p as B,x as t,m as s,e as m,S as p}from"./chunks/framework.Dvtg8yj2.js";const _=JSON.parse('{"title":"Llama-3.3","description":"","frontmatter":{"title":"Llama-3.3","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/llama-3-3.md","filePath":"llm/llama-3-3.md","lastUpdated":1788454257000}'),h={name:"llm/llama-3-3.md"};function d(c,a,u,A,E,T){const r=o("Mermaid");return l(),n("div",null,[a[1]||(a[1]=e('<h1 id="llama-3-3" tabindex="-1">Llama-3.3 <a class="header-anchor" href="#llama-3-3" aria-label="Permalink to &quot;Llama-3.3&quot;">​</a></h1><div class="epigraph"><p>Llama 3.3 是一个 70B 模型，能达到我们 405B 的表现，却更容易、更省成本地运行；靠的是包括在线偏好优化在内的后训练进展。</p><footer>—— Ahmad Al-Dahle（Meta 生成式 AI），Llama 3.3 发布说明，2024 年 12 月 6 日</footer></div><p>Llama 3.1 已经给出 8B / 70B / 405B 与 128K 窗口；405B 质量高，服务贵。2024 年 12 月 6 日 Meta 发布 <strong>Llama 3.3 70B Instruct</strong>：稠密、纯文本、多语对话向，公开权重只有这一档指令模型。官方叙事不是新骨干或更长预训练，而是用更新的后训练（SFT、RLHF，以及 Al-Dahle 点名的 online preference optimization）把 70B 的核心任务推到接近 3.1 405B Instruct。本篇只写模型卡与发布说明里能核对的规格和表，不把 3.3 说成新的 15T 从头预训练，也不把 <a href="/llm/llama-4">Llama 4</a> 的 MoE 提前安到这一代。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>3.1 70B Instruct 在通用知识上已经强，但指令遵循、数学、代码相对 405B 仍有缺口；405B 的显存、能耗与延迟让很多部署直接放弃。产品问题是：能否在<strong>同一套 70B 稠密 Transformer</strong> 上，只改后训练配方，把缺口补到「多数工作负载可以下换」？若可以，开源栈的缺省服务档就不必上 405B。若不可以，3.3 只是一次小幅刷分。</p><p>第二个问题是预期管理。「达到 405B 表现」是发布用语，模型卡里的表是分项的：有的指标 3.3 70B 超过 405B，有的仍落后。工程上必须按任务看表，不能把一句营销当成每一项基准的支配。</p><h3 id="_3-3-不是新的视觉型号-也不是新的-405b" tabindex="-1">3.3 不是新的视觉型号，也不是新的 405B <a class="header-anchor" href="#_3-3-不是新的视觉型号-也不是新的-405b" aria-label="Permalink to &quot;3.3 不是新的视觉型号，也不是新的 405B&quot;">​</a></h3><p>3.3 模型卡：文本入 / 文本与代码出，无图像。视觉仍停在 <a href="/llm/llama-3-2-vision">Llama 3.2</a>。没有 3.3 8B 或 3.3 405B 的同期公开指令档。架构栏写明 GQA、128K 上下文、15T+ token 量级的公开数据预训练、知识截止 <strong>2023 年 12 月</strong>——与 3.1 70B 同族。词表仍是 128256 量级 BPE。可以把它理解成 3.1 70B 骨干上的指令后训练升级版，而不是一次 Kaplan 曲线上的新预训练点。</p><p><span class="marginnote">HuggingFace 上检查点参数量常显示约 71B，来自实现计数；Meta 表写作 70B。配资源按 70B 稠密 BF16 规划即可，不要以为存在一个更小的「真·70B」隐藏档。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="后训练配方-公开到的部分" tabindex="-1">后训练配方（公开到的部分） <a class="header-anchor" href="#后训练配方-公开到的部分" aria-label="Permalink to &quot;后训练配方（公开到的部分）&quot;">​</a></h3><p>模型卡：在公开指令数据以及超过 <strong>2500 万</strong> 条合成样本上微调；对齐使用 SFT 与 RLHF，目标是帮助性与安全。Al-Dahle 额外指出采用包括 <strong>online preference optimization</strong> 在内的最新后训练技术。在线偏好相对离线 DPO 一类方法，会在训练过程中用当前策略采样再比较，数据分布跟着策略走，通常更贵，也更贴部署时的回复风格。具体学习率、偏好对数量、是否与 3.1 论文里的拒绝采样同一套流水线，官方没有写成可复现附录，本文不编。</p><p>预训练叙述与 3 系一致：约 15T 公开在线数据混合，截止 2023 年 12 月。3.3 的增量来自后训练，不应解读为又吃了新的一年互联网——知识截止没有前移到 2024。</p>',13)),(l(),B(p,null,{default:t(()=>[m(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22Llama%203%20%E7%B3%BB%2070B%20%E9%A2%84%E8%AE%AD%E7%BB%83%20~15T%20%2F%20%E6%88%AA%E6%AD%A2%202023-12%22%5D%20--%3E%20SFT%5B%22SFT%EF%BC%9A%E5%85%AC%E5%BC%80%E6%8C%87%E4%BB%A4%20%2B%202500%E4%B8%87%2B%20%E5%90%88%E6%88%90%22%5D%0A%20%20SFT%20--%3E%20ALIGN%5B%22RLHF%20%2F%20%E5%9C%A8%E7%BA%BF%E5%81%8F%E5%A5%BD%E4%BC%98%E5%8C%96%22%5D%0A%20%20ALIGN%20--%3E%20OUT%5B%22Llama%203.3%2070B%20Instruct%22%5D%0A%20%20OUT%20--%3E%20CMP%5B%22%E6%8C%89%E4%BB%BB%E5%8A%A1%E5%AF%B9%E7%85%A7%203.1%20405B%20Instruct%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="模型卡上的分项对照" tabindex="-1">模型卡上的分项对照 <a class="header-anchor" href="#模型卡上的分项对照" aria-label="Permalink to &quot;模型卡上的分项对照&quot;">​</a></h3><p>下列数字摘自 Meta Llama 3.3 模型卡（Instruct 档）。同一指标下同时列出 3.1 70B 与 3.1 405B，避免只报 3.3。</p><ul><li>MMLU CoT：3.3 与 3.1 70B 同为 86.0；405B 为 88.6。</li><li>MMLU-Pro CoT：3.3 为 68.9，高于 3.1 70B 的 66.4，低于 405B 的 73.3。</li><li>IFEval：3.3 为 92.1，高于 405B 的 88.6 与 3.1 70B 的 87.5。</li><li>GPQA Diamond CoT：3.3 为 50.5，略高于 405B 的 49.0。</li><li>HumanEval pass@1：3.3 为 88.4，接近 405B 的 89.0，明显高于 3.1 70B 的 80.5。</li><li>MATH CoT：3.3 为 77.0，高于 405B 的 73.8 与 3.1 70B 的 68.0。</li><li>BFCL v2 工具：3.3 为 77.3，与 3.1 70B 的 77.5 持平，低于 405B 的 81.1。</li><li>MGSM 多语：3.3 为 91.1，接近 405B 的 91.6。</li></ul><p>读法：指令遵循与数学上，70B 后训练升级甚至超过 405B；较难的综合知识（MMLU-Pro）与工具调用上，405B 仍领先。发布用语成立的范围是「核心对话与推理工作负载可下换」，不是「所有基准支配 405B」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是「容量已经够的 70B，瓶颈在对齐与推理格式，不在再堆稠密层」。3.1 70B 与 405B 的差距里，有一块可以被更好的 SFT 混合、合成思维链、在线偏好推平——尤其是 IFEval、MATH 这种对格式和步骤敏感的任务。MMLU-Pro 仍吃广度与参数，后训练补不齐。服务上 70B 的 KV、TP 宽度与能耗都按小一档计，这才是「更省成本」的物理含义：同一套 GQA、80 层量级、隐宽 8192 的 3.1 70B 配置，decode 带宽远低于 405B。</p><p>支持语言与 3.1 多语承诺一致：英语之外官方列德语、法语、意大利语、葡萄牙语、印地语、西班牙语、泰语。模型卡声明：其他语言或许能生成，但未达安全与帮助性门槛，不鼓励在未做微调与系统控制时当产品语言。上下文 128K 继承 3.1 的长窗课程，不是 3.3 新拉的窗口。RoPE 基数与 Llama 3 的高 \\(\\theta\\) 同族。</p><p><span class="marginnote">合成数据超过 2500 万条。许可上 Llama 社区许可允许用输出去训自己的模型，但应用侧仍要处理合成痕迹、评测污染与用户数据隔离。条数大不等于领域覆盖全，代码与工具要用自己的回归集。</span></p><h3 id="和-3-1-70b-instruct-替换时要注意什么" tabindex="-1">和 3.1 70B Instruct 替换时要注意什么 <a class="header-anchor" href="#和-3-1-70b-instruct-替换时要注意什么" aria-label="Permalink to &quot;和 3.1 70B Instruct 替换时要注意什么&quot;">​</a></h3><p>聊天模板、工具 JSON、系统提示若仍写 3.1 的习惯，3.3 通常能接，但 IFEval 变强也可能让模型更「较真」地执行过时系统提示。温度与 nucleus 应重扫，不要沿用 3.1 70B 的采样。安全分类器与 Llama Guard 版本要按 3.3 模型卡建议更新。知识仍停在 2023-12，需要 2024 事件的应用必须外挂检索，不能靠换 3.3 解决。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>没有官方 3.3 Base 对照表时，不要假设继续预训练会自动继承 Instruct 的数学增益。静态模型，线下数据，后续安全补丁以新版本为准。基准表是 Meta 自己的设定（shot 数、度量名称），第三方复现可能有差，引用应指向模型卡而不是二次图表。405B 在 MMLU-Pro 与 BFCL 上的领先对「硬知识 + 工具」产品仍有意义，下换前要在自己的工具集上测，不要只看 MATH。</p><p>不要把 3.3 写成 MoE 或视觉。不要把 Al-Dahle 的「405B 表现」理解成延迟也相同——70B 更快正是卖点。量化 4-bit 后与 3.1 70B 的相对排名可能变，后训练增益不是量化不变的。许可证是 Llama 3.3 社区许可，商用门槛与 3.1 类似，以当时文本为准。</p><p><span class="marginnote">服务引擎里 3.3 与 3.1 70B 的张量形状通常可共用同一套 TP/KV 内核。真正要换的是权重、tokenizer 配置里的特殊符号版本，以及聊天模板字符串。漏换模板会把「更强的指令遵循」用在错误的角色分隔符上，表现为胡言或拒答，而不是算力问题。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Llama 3.3 公开的是 70B Instruct：稠密纯文本、GQA、128K、知识截止 2023-12，2024-12-06 发布。</li><li>增量主要在后训练（SFT、RLHF、在线偏好优化与大规模合成数据），不是新的预训练体量。</li><li>模型卡上 IFEval、MATH、HumanEval 接近或超过 3.1 405B；MMLU-Pro 与工具调用仍是 405B 领先。</li><li>「达到 405B」指可下换的核心负载与成本，不是逐项支配。</li><li>无官方视觉档；语言支持八种达到门槛的语种。</li><li>出处：Meta Llama 3.3 模型卡；Ahmad Al-Dahle 2024-12-06 发布说明。</li></ul>',16))])}const M=i(h,[["render",d]]);export{_ as __pageData,M as default};
